// Material Icon Theme registry — auto-generated from every SVG
// sitting in `./material-icons/*.svg`. Two lookup tables:
//
//   • `fileIconsByExt[ext]?: ComponentType`   — file extension → SVG
//   • `fileIconsByName[name]?: ComponentType` — filename → SVG (configs)
//   • `folderIconsClosed[name]?: ComponentType` — folder name → SVG
//
// Every component is imported through Vite's `?react` suffix,
// which the `vite-plugin-svgr` plugin turns into a real React
// component that accepts standard `<svg>` props.
//
// **Open vs closed folder** — the upstream Material Icon Theme
// ships only the closed variant per folder (`folder-src.svg`);
// the `folder-src-open.svg` open variant is generated at build
// time and uses the *same* artwork. We follow the same pattern:
// one component per folder, used for both expansion states. The
// chevron row indicator already conveys the open/closed state.

import type { ComponentType, SVGProps } from "react";

type IconComponent = ComponentType<SVGProps<SVGSVGElement>>;

