/**
 * Resolve a folder basename to its icon component. Returns `null`
 * when the name isn't in the curated map — caller falls back to
 * the default amber codicon.
 */
export function getFolderIcon(folderName: string, _open: boolean): IconComponent | null {
  return folderIconsClosed[folderName] ?? null;
}

/**
 * Resolve a file basename to its icon component. Filename
 * overrides win over extension. Case-insensitive for the
 * extension; exact for the filename.
 */
export function getFileIcon(fileName: string): IconComponent | null {
  const byName = fileIconsByName[fileName];
  if (byName) return byName;
  const lower = fileName.toLowerCase();
  const byLowerName = fileIconsByName[lower];
  if (byLowerName) return byLowerName;
  const dot = lower.lastIndexOf(".");
  if (dot <= 0) return null;
  return fileIconsByExt[lower.slice(dot + 1)] ?? null;
}
